<template>
  <view class="seckill-page" :style="$themeStyle">
    <view class="sale-hero"><text class="sale-en">FLASH SALE</text><text class="sale-title">限时秒杀</text><text class="sale-copy">好物不等人，错过再等一天</text><view class="countdown"><text>距本场结束</text><text>{{hours}}</text><i>:</i><text>{{minutes}}</text><i>:</i><text>{{seconds}}</text></view><text class="bolt">⚡</text></view>
    <scroll-view scroll-x class="sessions"><view class="session-row"><view v-for="(s,i) in sessions" :key="s.time" :class="{active:i===active}" @tap="active=i"><text>{{s.time}}</text><text>{{s.label}}</text></view></view></scroll-view>
    <view class="sale-list"><view v-for="(item,i) in products.slice(0,5)" :key="item.id" class="sale-item card" @tap="open(item.id)"><view class="art sale-art" :class="'art-'+item.tone"><image v-if="item.image" class="product-image" :src="item.image" mode="aspectFill"/><text v-else class="art-icon">{{item.cover}}</text></view><view class="sale-info"><text class="item-title">{{item.title}}</text><text class="item-sub">{{item.subtitle}}</text><view class="progress"><view :style="{width:(35+i*11)+'%'}"></view></view><text class="stock">仅剩 {{8+i*5}} 件</text><view class="between"><view><text class="price">{{Math.round(item.price*.72)}}</text><text class="old">¥{{item.price}}</text></view><button @tap.stop="buy(item)">马上抢</button></view></view></view></view>
    <text class="notice">数量有限，售完即止</text>
  </view>
</template>
<script setup>
import{ref,onMounted,onUnmounted}from'vue';import{products}from'../../data/mock';import{requireLogin}from'../../utils/shop';const active=ref(1),hours=ref('01'),minutes=ref('28'),seconds=ref('36'),timer=ref();const sessions=[{time:'10:00',label:'已结束'},{time:'14:00',label:'抢购中'},{time:'18:00',label:'即将开始'},{time:'20:00',label:'即将开始'}];onMounted(()=>timer.value=setInterval(()=>seconds.value=String((Number(seconds.value)+59)%60).padStart(2,'0'),1000));onUnmounted(()=>clearInterval(timer.value));const open=id=>uni.navigateTo({url:`/pages/product/product?id=${id}`});const buy=item=>{uni.setStorageSync('buy_now',[{...item,price:Math.round(item.price*.72),quantity:1,checked:true}]);if(requireLogin('/pages/checkout/checkout?from=buy'))uni.navigateTo({url:'/pages/checkout/checkout?from=buy'})}
</script>
<style scoped>
.seckill-page{padding-bottom:50rpx}.sale-hero{height:350rpx;background:linear-gradient(135deg,var(--accent-start),var(--accent-end));color:#fff;padding:50rpx 34rpx;box-sizing:border-box;position:relative;overflow:hidden}.sale-en,.sale-title,.sale-copy{display:block;position:relative;z-index:2}.sale-en{font-size:18rpx;letter-spacing:5rpx;opacity:.5}.sale-title{font-size:58rpx;font-weight:700;margin-top:18rpx}.sale-copy{font-size:23rpx;opacity:.65;margin-top:12rpx}.countdown{display:flex;align-items:center;gap:8rpx;margin-top:32rpx;font-size:21rpx}.countdown text:not(:first-child){background:#fff;color:var(--ink);padding:8rpx 10rpx;border-radius:7rpx;font-weight:700}.countdown text:first-child{margin-right:8rpx}.countdown i{font-style:normal}.bolt{position:absolute;right:-30rpx;bottom:-45rpx;font-size:240rpx;opacity:.2}.sessions{white-space:nowrap;background:#fff}.session-row{display:inline-flex;min-width:100%;justify-content:space-around}.session-row view{padding:25rpx 32rpx;text-align:center;position:relative}.session-row text{display:block;font-size:20rpx;color:var(--muted)}.session-row text:first-child{font-size:30rpx;font-weight:700;color:var(--ink)}.session-row .active{color:var(--accent)}.session-row .active text{color:var(--accent)}.session-row .active::after{content:'';position:absolute;bottom:0;left:30%;width:40%;height:5rpx;background:var(--accent)}.sale-list{padding:26rpx}.sale-item{display:flex;padding:20rpx;margin-bottom:20rpx}.sale-art{width:220rpx;height:220rpx;border-radius:20rpx;flex-shrink:0}.sale-art .art-icon{font-size:75rpx}.sale-info{padding:5rpx 0 0 22rpx;flex:1;min-width:0}.item-title,.item-sub{display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.item-title{font-weight:700}.item-sub{font-size:21rpx;color:var(--muted);margin-top:7rpx}.progress{height:9rpx;background:#e9e4dc;border-radius:10rpx;margin-top:23rpx}.progress view{height:100%;background:var(--accent);border-radius:10rpx}.stock{display:block;font-size:18rpx;color:var(--accent);margin-top:6rpx}.sale-info .between{margin-top:15rpx}.sale-info .price{font-size:36rpx;color:var(--accent)}.old{font-size:20rpx;color:#aaa;text-decoration:line-through;margin-left:10rpx}.sale-info button{margin:0;background:var(--accent);color:#fff;font-size:22rpx;border-radius:40rpx;padding:0 25rpx}.notice{display:block;text-align:center;color:#aaa;font-size:19rpx}
</style>
